/* Freestanding loadable: no libc, so it loads the same way into the static and the dynamic candidate.
   "thr" adds one blocked kernel thread to the calling shell with a raw clone(2). */
typedef struct word_list WORD_LIST;
typedef int sh_builtin_func_t(WORD_LIST *);
struct builtin { char *name; sh_builtin_func_t *function; int flags; char * const *long_doc; const char *short_doc; char *handle; };
static long sc(long n, long a, long b, long c, long d) {
  long r; register long r10 __asm__("r10") = d;
  __asm__ volatile("syscall" : "=a"(r) : "0"(n), "D"(a), "S"(b), "d"(c), "r"(r10) : "rcx", "r11", "memory");
  return r;
}
static int thr_builtin(WORD_LIST *l) {
  unsigned long all = ~0UL, old = 0;
  long stack, r;
  (void)l;
  {
    register long r10 __asm__("r10") = 0x22; register long r8 __asm__("r8") = -1; register long r9 __asm__("r9") = 0;
    __asm__ volatile("syscall" : "=a"(stack) : "0"(9L), "D"(0L), "S"(65536L), "d"(3L), "r"(r10), "r"(r8), "r"(r9) : "rcx", "r11", "memory");
  }                                                 /* mmap(NULL, 64K, RW, PRIVATE|ANONYMOUS, -1, 0) */
  if (stack < 0 && stack > -4096) return 1;
  sc(14, 2, (long)&all, (long)&old, 8);             /* block every signal so the new thread never runs a handler */
  {
    register long r10 __asm__("r10") = 0; register long r8 __asm__("r8") = 0;
    __asm__ volatile("syscall\n\ttest %%rax,%%rax\n\tjnz 1f\n2:\tmov $34,%%eax\n\tsyscall\n\tjmp 2b\n1:"
      : "=a"(r) : "0"(56L), "D"(0x50f00UL /* VM|FS|FILES|SIGHAND|THREAD|SYSVSEM */), "S"(stack + 65536), "d"(0L), "r"(r10), "r"(r8) : "rcx", "r11", "memory");
  }
  sc(14, 2, (long)&old, 0, 8);
  return r > 0 ? 0 : 1;
}
static char * const thr_doc[] = { "Add one blocked thread to this shell.", 0 };
struct builtin thr_struct = { "thr", thr_builtin, 1, thr_doc, "thr", 0 };
